  const chrJuanna=article(byId,["Juanna di Ferrantino"]);if(chrJuanna){if(chrJuanna.pnj)chrJuanna.pnj.age="35 ans";setPublicTable(chrJuanna,"Âge","35 ans");moveParagraphs(chrJuanna,t=>/Née en 1940|sang angélique|Juanna di Bernardini|Vérité derrière le Voile/i.test(t));addMj(chrJuanna,[{type:"p",text:"Âge réel indiqué par la source : 95 ans."}]);ensurePublicSummary(chrJuanna,"reparation-realite-juanna","Biographie & informations publiques","Juanna di Ferrantino dirige les inquisiteurs de l’ordre de Magdalena. Son travail repose avant tout sur l’enquête, l’analyse de preuves, les dossiers internes et l’émission de mandats destinés aux chasseurs ou aux exorcistes.");replace(chrJuanna,[[/les mandats de chasses/gi,"les mandats de chasse"],[/cette dernière ne reconnait plus/gi,"cette dernière ne reconnaît plus"],[/réflexions assez juste/gi,"réflexions assez justes"]]);}
