  const chrLuciana=article(byId,["Luciana Saltarelli","Sœur Lucia"]);if(chrLuciana){if(chrLuciana.pnj)chrLuciana.pnj.age="32 ans";setPublicTable(chrLuciana,"Âge","32 ans");moveParagraphs(chrLuciana,t=>/Verenzio Imburgia|Luciabella Imburgia|vampire|semi-vampire|dhampire|Diurne|rose sanguine|sang d’un autre vampire|loups-garous/i.test(t));ensurePublicSummary(chrLuciana,"reparation-realite-luciana","Biographie & informations publiques","Luciana Saltarelli, dite « Sœur Lucia », est une abbesse de l’ordre d’Arianwen et une chasseuse de terrain. Elle privilégie le combat rapproché, déteste les armes à distance et travaille habituellement en binôme avec Sœur Leena.");replace(chrLuciana,[[/Sœur Lucia/gi,"Sœur Lucia"]]);}
  const chrNazarena=article(byId,["Nazarena Montenegro"]);if(chrNazarena){if(chrNazarena.pnj)chrNazarena.pnj.age="49 ans";setPublicTable(chrNazarena,"Âge","49 ans");moveParagraphs(chrNazarena,t=>/puissant artefact|inquisition la retrouva|tué elle-même de nombreux politiciens|sectes de fléaux|Grand Savoir/i.test(t));ensurePublicSummary(chrNazarena,"reparation-realite-nazarena","Biographie & informations publiques","Nazarena Montenegro est une ancienne criminelle madrilène devenue commissaire de l’ordre de Magdalena. Après avoir perturbé une enquête religieuse, elle choisit de collaborer avec l’ordre et y gagna progressivement une place importante grâce à son caractère outrancier et à ses méthodes sans limites.");replace(chrNazarena,[[/Espagole/gi,"Espagnole"],[/des plus importante/gi,"des plus importantes"],[/faire renaitre/gi,"faire renaître"]]);}
  const chrOkeenan=article(byId,["Okeenan Degath"]);if(chrOkeenan){if(chrOkeenan.pnj)chrOkeenan.pnj.age="41 ans";setPublicTable(chrOkeenan,"Âge","41 ans");moveParagraphs(chrOkeenan,t=>/La vérité est bien plus sombre|résipiscent|\bOg\b|\bDive\b|Akvan|daemons|Archanges|Rasgado|sorts surpuissants|bagues préalablement/i.test(t));ensurePublicSummary(chrOkeenan,"reparation-realite-okeenan","Biographie & informations publiques","Okeenan Degath a servi dans les US Marines avant la guerre. Traumatisé par le conflit, il trouva ensuite sa voie dans la religion et fut repéré par l’ordre d’Arianwen, où il exerce comme abbé de terrain.");replace(chrOkeenan,[[/un US marines/gi,"un US Marine"],[/connait très bien/gi,"connaît très bien"],[/a recourt à/gi,"a recours à"]]);}
